INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(23801, 'Luke 1:35', 'Luke', 1, 35, '&nbsp;فرښتې جواب ورکړو، ”روحُ القُدس به په تا نازل شى او د خُدائ تعالىٰ قُدرت به په تا سورے وکړى او په دې وجه به هغه مقدس ماشوم د خُدائ پاک زوئ بللے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23802, 'Luke 1:36', 'Luke', 1, 36, '&nbsp;بله دا چې ستا خپلوانه اليشبع هم اُميدواره ده او په زوړ عُمر به زوئ راوړى او څوک چې په شنډه مشهوره وه، د هغې د اُميدوارۍ شپږمه مياشت ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23803, 'Luke 1:37', 'Luke', 1, 37, '&nbsp;ځکه چې هيڅ يو کار د خُدائ پاک دپاره ناممکنه نۀ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23804, 'Luke 1:38', 'Luke', 1, 38, '&nbsp;مريم وفرمائيل چې، ”زۀ د مالِک خُدائ وينځه يم. تا چې څۀ فرمائيلى دى، هم داسې دې وشى.“ بيا فرښته د هغې نه لاړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23805, 'Luke 1:39', 'Luke', 1, 39, '&nbsp;په دغه وخت مريم نېغه راپاڅېدله او يو ښار ته لاړه کوم چې د يهوداه په غريزه علاقه کښې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23806, 'Luke 1:40', 'Luke', 1, 40, '&nbsp;هغه د زکرياه کره ورغله او په اليشبع يې سلام واچولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23807, 'Luke 1:41', 'Luke', 1, 41, '&nbsp;کله چې اليشبع د مريمې سلام واورېدو نو ماشوم د هغې په ګېډه کښې په ټوپونو شو نو اليشبع د روحُ القُدس نه معموره شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23808, 'Luke 1:42', 'Luke', 1, 42, '&nbsp;او په زوره يې ووئيل، ”په ټولو ښځو کښې تۀ مبارکه يې او ستا د ګېډې مېوه مبارکه ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23809, 'Luke 1:43', 'Luke', 1, 43, '&nbsp;زۀ څوک يم چې زما د مالِک مور دې زما تپوس له راشى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23810, 'Luke 1:44', 'Luke', 1, 44, '&nbsp;چې څنګه ستا سلام زما تر غوږو شو نو زما په ګېډه کښې زما بچى ټوپ ووهلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23811, 'Luke 1:45', 'Luke', 1, 45, '&nbsp;څومره بختوره ده هغه چې په دې يې ايمان دے چې د مالِک خُدائ قول به پوره شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23812, 'Luke 1:46', 'Luke', 1, 46, '&nbsp;او مريمې وفرمائيل چې، ”اے زما زړۀ. د مالِک خُدائ لوئى بيان کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23813, 'Luke 1:47', 'Luke', 1, 47, '&nbsp;اے زما زړۀ. خوشحالى وکړه، خوشحالى وکړه. زما د خلاصوونکى خُدائ پاک په نوم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23814, 'Luke 1:48', 'Luke', 1, 48, '&nbsp;چې هغۀ د خپلې عاجزې وينځې په حال دومره لوئ نظر کړے دے. د نن ورځې نه پس به راتلونکى ټولې پيړۍ ما ته بختوره وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23815, 'Luke 1:49', 'Luke', 1, 49, '&nbsp;ځکه هغۀ زما دپاره دومره لوئ کارونه کړى دى. د هغۀ نوم پاک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23816, 'Luke 1:50', 'Luke', 1, 50, '&nbsp;او څوک چې د هغۀ نه يريږى، په هغوئ د هغۀ رحم پيړۍ په پيړۍ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23817, 'Luke 1:51', 'Luke', 1, 51, '&nbsp;او هغه کارونه چې د هغۀ لاس کړى دى، د هغۀ قوت څرګندوى. کبرژن او مغروره يې په خپلو خيالونو سره دانه وانه کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23818, 'Luke 1:52', 'Luke', 1, 52, '&nbsp;هغۀ حکمرانان د تختُونو نه راغورزولى دى خو غريبانان يې لويو مرتبو ته رسولى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23819, 'Luke 1:53', 'Luke', 1, 53, '&nbsp;اوږى يې په ښۀ څيزونو ماړۀ کړى دى او مالدار يې تش لاس شړلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23820, 'Luke 1:54', 'Luke', 1, 54, '&nbsp;هغۀ د خپل خادِم بنى اِسرائيل مدد کړے دے، لکه چې زمونږ نيکونو ته هغۀ وئيلى وُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23821, 'Luke 1:55', 'Luke', 1, 55, '&nbsp;هغۀ په اِبراهيم او د هغۀ په اولاد رحم کول چرې هېر نۀ کړل.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23822, 'Luke 1:56', 'Luke', 1, 56, '&nbsp;مريم د اليشبع سره درې مياشتې پاتې شوه او بيا کور ته واپس راغله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23823, 'Luke 1:57', 'Luke', 1, 57, '&nbsp;بيا د اليشبع د بچى پېدا کېدو وخت پوره شو او د هغې زوئ پېدا شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23824, 'Luke 1:58', 'Luke', 1, 58, '&nbsp;هر کله چې د هغې ګاونډيانو او خپلوانو دا واورېدل نو ډېره زياته خوشحالى يې ورسره وکړه چې مالِک خُدائ پرې لوئ رحم وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23825, 'Luke 1:59', 'Luke', 1, 59, '&nbsp;او هغوئ په اتمه ورځ بيا راغلل چې ماشوم سنت کړى او هغوئ دا غوښتل چې د هغۀ د پلار نوم زکرياه پرې کېږدى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23826, 'Luke 1:60', 'Luke', 1, 60, '&nbsp;خو د هغۀ مور ورته ووئيل چې، ”نه. دے به يحيىٰ بللے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23827, 'Luke 1:61', 'Luke', 1, 61, '&nbsp;خو هغوئ ووئيل چې، ”ستا په خاندان کښې خو د هيچا هم داسې نوم نشته.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23828, 'Luke 1:62', 'Luke', 1, 62, '&nbsp;بيا هغوئ د هغۀ د پلار نه په اِشارو تپوس وکړو چې، ”د دۀ نوم څۀ اېښودل په کار دى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23829, 'Luke 1:63', 'Luke', 1, 63, '&nbsp;هغۀ د ليکلو يوه تختۍ راوغوښته او په دې ټول حېران شول چې هغۀ دا وليکل چې، ”د دۀ نوم به يحيىٰ وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23830, 'Luke 1:64', 'Luke', 1, 64, '&nbsp;سمدستى د هغۀ شونډې او ژبه آزاد شول او هغه ګويا شو او د خُدائ پاک ثنا يې ووئيله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23831, 'Luke 1:65', 'Luke', 1, 65, '&nbsp;ټول ګاونډيان په دې خبره هيبت واخستل او دا خبرې د يهوديه په غريزه علاقه کښې هرې خوا ته خورې شولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23832, 'Luke 1:66', 'Luke', 1, 66, '&nbsp;چا چې دا واورېدل په هغوئ ډېر اثر وشو او وې وئيل چې، ”د دې ماشوم نه به څۀ جوړيږى؟“ ځکه چې د مالِک خُدائ لاس د دۀ په سر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23833, 'Luke 1:67', 'Luke', 1, 67, '&nbsp;بيا د هغۀ پلار زکرياه د روحُ القُدس نه معمور شو او دا پېشګوئې يې وکړه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23834, 'Luke 1:68', 'Luke', 1, 68, '&nbsp;”ثنا دې وى د بنى اِسرائيل په مالِک خُدائ پاک، ځکه چې هغۀ په خپلو بنديانو نظر وکړو، او هغوئ يې په بيعه واخستل او آزاد يې کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23835, 'Luke 1:69', 'Luke', 1, 69, '&nbsp;او د خپل خادِم داؤد په کور کښې يې يو زورَور خلاصونکے پېدا کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23836, 'Luke 1:70', 'Luke', 1, 70, '&nbsp;او لکه چې هغۀ د وړومبو مقدسو نبيانو په خولۀ څو پيړۍ وړاندې وعده کړې وه', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23837, 'Luke 1:71', 'Luke', 1, 71, '&nbsp;چې هغه به مونږ د خپلو دشمنانو نه خلاص کړى او د هغوئ ټولو د لاسونو نه څوک چې راسره کينه ساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23838, 'Luke 1:72', 'Luke', 1, 72, '&nbsp;او دا چې هغه به زمونږ په پلار نيکۀ رحم وکړى او خپله مقدسه وعده به ياده ساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23839, 'Luke 1:73', 'Luke', 1, 73, '&nbsp;هم دا قَسم هغۀ زمونږ د پلار اِبراهيم سره کړے وو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23840, 'Luke 1:74', 'Luke', 1, 74, '&nbsp;چې هغه به مونږ د دشمنانو د لاسه بچ ساتى، او د يرې نه به امان راکړى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23841, 'Luke 1:75', 'Luke', 1, 75, '&nbsp;چې مونږ ټول عُمر په پاکۍ او په صداقت د هغۀ عبادت وکړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23842, 'Luke 1:76', 'Luke', 1, 76, '&nbsp;او اے زما وړوکيه، تۀ به د خُدائ تعالىٰ نبى بللے شې ځکه چې تۀ به د مالِک په وړاندې تير شې چې د هغۀ لارې تيارې کړې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23843, 'Luke 1:77', 'Luke', 1, 77, '&nbsp;او تۀ به د هغۀ خلق په دې پوهه کړې چې خلاصون د ګناهونو په معافۍ کښې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23844, 'Luke 1:78', 'Luke', 1, 78, '&nbsp;زمونږ د خُدائ پاک د خالص رحم په وجه به د سحر نمر په مونږ راوخېژى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23845, 'Luke 1:79', 'Luke', 1, 79, '&nbsp;او په هغوئ به وځليږى څوک چې په تيارۀ کښې او د مرګ په سورى کښې ناست وى او چې زمونږ قدمونه د خير او سلامتۍ په لاره سم کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23846, 'Luke 1:80', 'Luke', 1, 80, '&nbsp;څنګه چې دغه ماشوم لوئېدو نو روحانى قوت يې موندو او تر هغې ورځې پورې په بيابان کښې اوسېدو ترڅو چې هغه بنى اِسرائيلو ته ښکاره راڅرګند شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23847, 'Luke 2:1', 'Luke', 2, 1, '&nbsp;په هغه ورځو کښې د رومى قيصر اوګوستوس د طرف نه دا فرمان جارى شو چې په رومى بادشاهۍ کښې دې د ټولو خلقو مردم‌شمارى وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23848, 'Luke 2:2', 'Luke', 2, 2, '&nbsp;دا وړومبۍ مردم‌شمارى وه چې د شام د ګورنر کيرينيوس په وخت کښې وشوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23849, 'Luke 2:3', 'Luke', 2, 3, '&nbsp;د دې دپاره هر يو کس خپلې خپلې ښاريې ته د مردم‌شمارۍ دپاره لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23850, 'Luke 2:4', 'Luke', 2, 4, '&nbsp;نو دغه شان يوسف هم د ګليل د ناصرت نه يهوديه ته لاړو چې د داؤد په ښاريه بيت‌لحم کښې خپل نوم وليکى ځکه چې هغه د داؤد د خاندان نه وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23851, 'Luke 2:5', 'Luke', 2, 5, '&nbsp;او هغه سره د مريمې لاړو څوک چې د هغۀ چنغله وه او هغه د مخکښې نه اُميدواره وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23852, 'Luke 2:6', 'Luke', 2, 6, '&nbsp;او کله چې هغوئ لا هلته کښې وُو نو د هغې ماشوم د پېدا کېدو ورځې پوره شوې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23853, 'Luke 2:7', 'Luke', 2, 7, '&nbsp;او د هغې اول زوئ پېدا شو. هغې هغه په اوړنى کښې ونغښتو او په يو اخور کښې يې کېښودو ځکه چې په سرائى کښې د هغوئ دپاره ځائ نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23854, 'Luke 2:8', 'Luke', 2, 8, '&nbsp;هم په دغه علاقه کښې څۀ شپونکى وُو چې په پټو کښې يې د شپې د خپلو رمو څوکيدارى کوله،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23855, 'Luke 2:9', 'Luke', 2, 9, '&nbsp;چې ناګهانه د مالِک خُدائ فرښته د هغوئ په وړاندې راڅرګنده شوه او د مالِک خُدائ نُور د هغوئ چارچاپيره خور شو او هغوئ يرې واخستل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23856, 'Luke 2:10', 'Luke', 2, 10, '&nbsp;خو فرښتې هغوئ ته وفرمائيل چې، ”يرېږئ مه. ما تاسو له يو ښۀ زېرے راوړے دے چې د ټولو خلقو دپاره به يوه لويه خوشحالى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23857, 'Luke 2:11', 'Luke', 2, 11, '&nbsp;نن د داؤد په ښار کښې ستاسو خلاصونکے پېدا شوے دے چې هغه مسيح مالِک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23858, 'Luke 2:12', 'Luke', 2, 12, '&nbsp;او ستاسو دپاره د هغۀ دا نښه ده چې تاسو به يو ماشوم په اوړنى کښې انغښتے په اخور کښې ومومئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23859, 'Luke 2:13', 'Luke', 2, 13, '&nbsp;ناګهانه د هغې فرښتې سره د آسمانى لښکر يوه ډله راڅرګنده شوه او د خُدائ پاک دا ثنا يې ووئيله چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23860, 'Luke 2:14', 'Luke', 2, 14, '&nbsp;”د خُدائ پاک حمد دې وى پاس په آسمان کښې، او په زمکه دې د هغه خلقو دپاره خير او سلامتى وى د چا نه چې هغه رضا دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23861, 'Luke 2:15', 'Luke', 2, 15, '&nbsp;کله چې فرښتې د هغه ځايه آسمان طرف ته رُخصت شوې نو شپونکو يو تر بله ووئيل، ”ځئ چې اوس سمدستى بيت‌لحم ته لاړ شُو او دا شوے کار ووينو کوم چې مالِک خُدائ مونږ ته څرګند کړے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23862, 'Luke 2:16', 'Luke', 2, 16, '&nbsp;هغوئ په منډه لاړل د مريمې او يوسف پته يې ولګوله او هغه ماشوم يې په اخور کښې پروت وموندلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23863, 'Luke 2:17', 'Luke', 2, 17, '&nbsp;کله چې هغوئ هغه ماشوم وليدو نو زر يې دا خبره خوره کړه څۀ چې دوئ ته د هغۀ په حقله وئيلے شوى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23864, 'Luke 2:18', 'Luke', 2, 18, '&nbsp;او د دې شپونکو خبره چې چا واورېدله، ټول حق حېران شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23865, 'Luke 2:19', 'Luke', 2, 19, '&nbsp;خو مريمې په دې ټولو واقعو سوچ کولو او په زړۀ کښې يې ساتلى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23866, 'Luke 2:20', 'Luke', 2, 20, '&nbsp;خو شپونکو په واپس تلو کښې د خُدائ پاک ثناء صِفت بيانولو ځکه چې بلکل هر څۀ يې هغه شان وليدل او واورېدل لکه څنګه چې فرښتې ورته فرمائيلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23867, 'Luke 2:21', 'Luke', 2, 21, '&nbsp;اتۀ ورځې پس هغه سنت شو او د هغۀ نوم يې عيسىٰ کېښودو. دا هغه نوم وو چې د هغۀ د مور په ګېډه کېدو نه مخکښې فرښتې په هغۀ اېښودے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23868, 'Luke 2:22', 'Luke', 2, 22, '&nbsp;نو د موسىٰ د شريعت په مطابق چې د هغوئ د څلوېښتۍ ورځې پوره شوې نو يروشلم ته يې بوتلو چې مالِک خُدائ ته يې پېش کړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23869, 'Luke 2:23', 'Luke', 2, 23, '&nbsp;لکه چې د مالِک خُدائ په شريعت کښې ليکلى دى چې، ”هر وړومبے نر ماشوم چې پېدا شى هغه به مالِک خُدائ ته وقف شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23870, 'Luke 2:24', 'Luke', 2, 24, '&nbsp;نو هغوئ بيا د مالِک خُدائ د شريعت په مطابق قربانى وکړه، يعنې يوه د کُړکوړو جوړه يا د کونترو دوه بچى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23871, 'Luke 2:25', 'Luke', 2, 25, '&nbsp;په هغه ورځو کښې په يروشلم کښې شمعون نومې يو سړے وو. هغه رښتينے او پرهيزګاره وو، څوک چې د بنى اِسرائيلو د بچ کېدو په طمع وو او د روحُ القُدس نه معمور وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23872, 'Luke 2:26', 'Luke', 2, 26, '&nbsp;روحُ القُدس هغۀ ته دا پېغام ورکړے وو، ترڅو پورې چې تا د مالِک خُدائ مسيح ليدلے نۀ وى تر هغې به تۀ نۀ مرې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23873, 'Luke 2:27', 'Luke', 2, 27, '&nbsp;نو هغه د روحُ القُدس په هدايت د خُدائ کور ته راغلو. او کله چې د عيسىٰ مور پلار هغه ماشوم عيسىٰ دننه راوړو چې د شريعت په مطابق يې خُدائ ته وقف کړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23874, 'Luke 2:28', 'Luke', 2, 28, '&nbsp;نو شمعون هغه په غېږ کښې واخستو او د خُدائ پاک ثنا يې ووئيله، او داسې يې ووئيل چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23875, 'Luke 2:29', 'Luke', 2, 29, '&nbsp;”اے مالِکه، نن تۀ خپل خادِم د خپلې وعدې په مطابق په سلامتۍ سره رخصتوې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23876, 'Luke 2:30', 'Luke', 2, 30, '&nbsp;ځکه چې ما په خپلو سترګو ستا هغه خلاصون وليدلو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23877, 'Luke 2:31', 'Luke', 2, 31, '&nbsp;چې تا د ټولو قومونو په وړاندې تيار کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23878, 'Luke 2:32', 'Luke', 2, 32, '&nbsp;هغه به د د غېر‌يهوديانو دپاره رڼا وى او بنى اِسرائيلو ته به جلال ورکړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23879, 'Luke 2:33', 'Luke', 2, 33, '&nbsp;د ماشوم مور او پلار هغه خبرو ته ګوته په خولۀ وو کومې خبرې چې د هغۀ په حقله وئيلے شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23880, 'Luke 2:34', 'Luke', 2, 34, '&nbsp;بيا شمعون د هغۀ دپاره برکت وغوښتو او د هغۀ مور مريمې ته يې ووئيل چې، ”دا ماشوم په بنى اِسرائيلو کښې د ډېرو د بربادېدو او آبادېدو دپاره مقرر شوے دے، او د خُدائ پاک د طرف نه داسې نښه ده چې ډېر خلق به د هغۀ مخالفت کوى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23881, 'Luke 2:35', 'Luke', 2, 35, '&nbsp;ځکه چې د ډېرو خلقو د زړُونو پټ خيالونه به ښکاره شى. او د غم په وجه به ستا حال داسې وى لکه ستا زړۀ چې په تُوره وهلے شوے وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23882, 'Luke 2:36', 'Luke', 2, 36, '&nbsp;په دغه ورځو کښې د آشر په خيل کښې حناه نومې يوه پېغمبره وه څوک چې د فنواېل لور وه. هغه ډېره بوډۍ ښځه وه او د وادۀ په اوؤم کال کونډه شوې وه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23883, 'Luke 2:37', 'Luke', 2, 37, '&nbsp;او بيا د څلورو اتياو کالو پورې کونډه وه. هغې د خُدائ د کور د تلو راتلو پابندى کوله، شپه او ورځ به يې روژې ساتلې او دُعا به يې کوله', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23884, 'Luke 2:38', 'Luke', 2, 38, '&nbsp;نو په هغه ساعت هغه راغله او د خُدائ پاک شُکر يې وکړو. نو هغې هغه ټولو خلقو ته د هغه ماشوم په حقله خبرې وکړې چې د يروشلم د آزادۍ په اِنتظار وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23885, 'Luke 2:39', 'Luke', 2, 39, '&nbsp;هرکله چې يوسف او مريم د مالِک خُدائ د شريعت په مطابق هر څۀ پوره کړل نو هغوئ په ګليل کښې خپلې ښاريې ناصرت ته واپس شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23886, 'Luke 2:40', 'Luke', 2, 40, '&nbsp;نو دغه ماشوم لوئېدو، قوت او حکمت يې موندلو او د خُدائ پاک فضل ورسره وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23887, 'Luke 2:41', 'Luke', 2, 41, '&nbsp;د عيسىٰ مور پلار به هر کال يروشلم ته د فسحې اختر له تلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23888, 'Luke 2:42', 'Luke', 2, 42, '&nbsp;او چې هغه د دولسو کالو شو نو هغوئ د خپل دستور په مطابق د اختر دپاره لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23889, 'Luke 2:43', 'Luke', 2, 43, '&nbsp;نو چې د اختر ورځې پوره شوې او هغوئ کور ته واپس روان شول نو عيسىٰ په يروشلم کښې ايسار شو خو مور پلار ته يې پته نۀ وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23890, 'Luke 2:44', 'Luke', 2, 44, '&nbsp;او هغوئ ټوله ورځ په دې خيال سفر وکړو چې ګنې هغه به په قافله کښې چرته وى، خو ماښام يې بيا په خپلو خپلوانو او دوستانو کښې د هغۀ لټون شروع کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23891, 'Luke 2:45', 'Luke', 2, 45, '&nbsp;چې وې نۀ موندلو نو يروشلم ته راواپس شول چې هلته يې ولټوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23892, 'Luke 2:46', 'Luke', 2, 46, '&nbsp;په درېمه ورځ يې هغه د خُدائ په کور کښې ناست وموندلو چې د اُستاذانو سره ناست وو او د هغوئ خبرو ته يې غوږ نيولے وو او تپوسونه يې ترې کول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23893, 'Luke 2:47', 'Luke', 2, 47, '&nbsp;او هغوئ ټول چا چې د هغۀ خبرې واورېدې، د هغۀ په پوهه او په جوابونو اريان دريان وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23894, 'Luke 2:48', 'Luke', 2, 48, '&nbsp;مور پلار د هغۀ په ليدو حق حېران شول او د هغۀ مور ورته ووئيل چې، ”زويه. تا مونږ سره داسې ولې وکړل؟ ستا پلار او ما تۀ ډېر په فکرمندۍ سره لټولې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23895, 'Luke 2:49', 'Luke', 2, 49, '&nbsp;هغۀ ورته وفرمائيل چې، ”تاسو زۀ ولې لټولم؟ تاسو ته پته نۀ وه چې ما ته د خپل پلار په کور کښې پاتې کېدل په کار وو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23896, 'Luke 2:50', 'Luke', 2, 50, '&nbsp;خو هغوئ د هغۀ د خبرې په مطلب ونۀ رسېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23897, 'Luke 2:51', 'Luke', 2, 51, '&nbsp;بيا هغه د هغوئ سره ناصرت ته واپس لاړو او د هغوئ د تابعدارۍ لاندې يې وخت تېرولو. مور يې دا ټولې خبرې په زړۀ کښې پټې وساتلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23898, 'Luke 2:52', 'Luke', 2, 52, '&nbsp;او د عيسىٰ حِکمت او ونه لوئېدل او د خُدائ پاک او د بنى آدمو په نظر کښې يې قبوليت وموندو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23899, 'Luke 3:1', 'Luke', 3, 1, '&nbsp;د قيصر تيبريوس د حکومت په پينځلسم کال کښې پنطوس پيلاطوس د يهوديه ګورنر وو او هيروديس د ګليل ګورنر، د هغۀ ورور فيليپوس د اِتُوريه او تراخونيتيس او ليسانياس د ابيلينے ګورنران وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23900, 'Luke 3:2', 'Luke', 3, 2, '&nbsp;د مشرانو اِمامانو اناس او کائفس په وخت کښې د زکرياه په زوئ يحيىٰ باندې په بيابان کښې د خُدائ پاک کلام نازل شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');